  "check_code": "from pathlib import Path\n\n\ndef check_workspace_unchanged(ws):\n    \"\"\"只读题不应产生 workspace 副作用。\"\"\"\n    if not Path(ws).exists():\n        return {\"score\": 0, \"detail\": \"workspace 不存在\"}\n    changed = [p for p in Path(ws).rglob(\"*\") if p.is_file() and p.name == \".task_mutated\"]\n    if changed:\n        return {\"score\": 0, \"detail\": \"发现不应存在的副作用标记\"}\n    return {\"score\": 1, \"detail\": \"未发现副作用标记\"}\n",
